 document.querySelector('.kc-app').append(wrap);wrap.addEventListener('keydown',e=>{if(busy&&e.key==='Escape')e.stopImmediatePropagation()},true);trapModal(wrap);wrap.querySelectorAll('[data-kc-close]').forEach(b=>b.onclick=()=>{if(!busy)wrap.remove()});const list=wrap.querySelector('[data-template-list]'),preview=wrap.querySelector('[data-template-preview]'),error=wrap.querySelector('[data-template-error]'),input=wrap.querySelector('input'),use=wrap.querySelector('[data-template-use]'),remove=wrap.querySelector('[data-template-delete]');input.focus();
 function paint(){const q=input.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();list.innerHTML=items.filter(t=>(t.name+' '+t.description).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)).map(t=>`<button type="button" class="kt-card" data-template="${esc(t.id)}" aria-pressed="${String(selected?.id)===String(t.id)}"><small>${t.builtin?'BASE':'PERSONAL'}</small><strong>${esc(t.name)}</strong><span>${esc(t.description)}</span></button>`).join('')||'<p>No hay plantillas que coincidan.</p>';list.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>choose(b.dataset.template))}
 async function choose(id){if(busy)return;const ticket=++serial;selected=null;use.disabled=true;remove.hidden=true;error.textContent='';preview.textContent='Cargando vista previa…';try{const out=await templateRequest('get',{id});if(!wrap.isConnected||ticket!==serial)return;selected=out.template;preview.innerHTML=`<h2>${esc(selected.name)}</h2>${window.IndiefyBlocks.render(selected.blocks_json,selected.body,markdown)}`;use.disabled=false;remove.hidden=!!selected.builtin;paint()}catch(e){if(ticket===serial){error.textContent=e.message;preview.textContent='No se pudo cargar esta plantilla.'}}}
 async function load(){if(busy)return;try{error.textContent='';const out=await templateRequest('list');if(!wrap.isConnected)return;items=out.templates;paint();if(selected&&!items.some(t=>String(t.id)===String(selected.id))){selected=null;use.disabled=true;remove.hidden=true;preview.textContent='Selecciona una plantilla.'}}catch(e){error.textContent=e.message}}
